update public.content_blocks
set text = 'טיול לממפיס וסקארה הוא טיול ייחודי המשלב שני אתרים היסטוריים ומשמעותיים במצריים ובתרבות המצרית. ממפיס הייתה בירת מצרים העתיקה, וסקארה הייתה עיר הקברים שלה. בממפיס נמצא פסל ענק של רעמסס השני, ובסקארה נמצאת הפירמידה הראשונה שנבנתה בהיסטוריה, הפירמידה של ג’וסר. עם חברת טיולי העולם העתיק אתם תחוו טיול מלא בחוויות בלתי נשכחות לאורך כל הטיול. הצוות […]'
