update public.content_blocks
set text = 'שני המקדשים נבנו על ידי הפרעונים סתי הראשון ורעמסס השני, בין השנים 1284 לפנה”ס ל־1264 לפנה”ס לערך. המקדשים ניצלו ושוחזרו כאשר עבודות השימור החלו כבר בשנות ה-60 המוקדמות. יחד עם חברת טיולי העולם העתיק נחווה יחד את החוויה היוצאת דופן ונחיה את מצרים העתיקה ונרגיש את רוח הדברים לצד סיפורים מרהיבים ומלאים בהיסטוריה מצמררת.'
