update public.content_blocks
set text = 'טיול לממפיס סקארה מתאים לאוכלוסיה מגוונת ומתאימה לאנשים בגילאים שונים. הטיול יכול להתאים לזוגות שמחפשים טיול בסגנון אחרי ומרתק, זוגות מבוגרים יותר שסוף סוף יש להם זמן פנוי ורוצים לבלות יחד ולצבור עוד חוויות, קבוצות קטנות וקבוצות גדולות. גם חברות בסדרי גודל השונים, ארגונים וגופים נוספים יכולים להעניק טיול למצרים לצוותי העובדים שלהם, קבוצות של מנהלים ואנשי פתח של הארגון. טיול זה יכול להיות מתנה מושלמת עבור מישהו שאתם מאוד אוהבים ומחפשים מלתת להם מתנה שונה, מקורית וייחודית. עם חברת טיולי העולם העתיק אתם יכולים להגשים את החלום ולחוות רגעים בלתי נשכחים. הצוות שלנו יכוון אתכם ויתאים עבורכם את המסלול המושלם.'
