update public.content_blocks
set text = 'נטלתי חלק בסיור לצפון יוון. אני עצמי עוסק בתיירות מאז 1977, ובקי מאוד בלוגיסטיקה הלא פשוטה של ארגון טיולים. דירגתי את הסיור ב 5 כוכבים, ולו היו כוכבים נוספים, הייתי מוסיף. נרשמתי לסיור בזכות היכרותי המוקדמת עם מדריך הסיור, ד״ר אייל מירון, איש אשכולות, אנציקלופדיה מהלכת. במהלך הסיור למדתי להכיר את רוני […], שליווה אישית את הסיור על מנת לוודא שכל פרט ופרט מהלוגיסטיקה המתוכננת יתבצע כראוי. אין בפי מילים אלא דברי שבח לתיירות מקצועית במיטבה. למתעניינים בסיור מעמיק - זאת הכתובת.'
