update public.content_blocks
set text = 'ביצוע הטיול מותנה במינימום משתתפים במידה ולא ייצא הטיול מסיבה זאת. טיולי העולם העתיק תחזיר את כל הכספים ששולמו למעט הוצאת ויזה באם הייתה כזאת ולא תהיה כל טענה נוספת כלפי טיולי העולם העתיק או מי מטעמה'
